selector_to_html = {"a[href=\"#ppu\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">PPU<a class=\"headerlink\" href=\"#ppu\" title=\"Link to this heading\">#</a></h3><p>PPU \u8868\u73b0\u4e3a CUDA \u517c\u5bb9\u8bbe\u5907\uff1a\u5176 torch wheel \u662f\u5b8c\u6574\u7684 CUDA 13 \u6784\u5efa\uff0c\u5e76\u5728 <code class=\"docutils literal notranslate\"><span class=\"pre\">CUDA</span></code> dispatch key \u4e0b\u6ce8\u518c\u7b97\u5b50\uff0c\u56e0\u6b64\u4e0d\u9700\u8981\u5b98\u65b9 <code class=\"docutils literal notranslate\"><span class=\"pre\">+cpu</span></code> wheel\uff0c\u4e5f\u4e0d\u9700\u8981\u5916\u90e8 <code class=\"docutils literal notranslate\"><span class=\"pre\">libtorch_cuda.so</span></code>\u3002</p>", "a[href=\"#gcu\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u71e7\u539f GCU<a class=\"headerlink\" href=\"#gcu\" title=\"Link to this heading\">#</a></h3><p>\u9700\u8981 TopsRider SDK\uff08<code class=\"docutils literal notranslate\"><span class=\"pre\">libtopsrt.so</span></code> \u8fd0\u884c\u65f6\u4e0e <code class=\"docutils literal notranslate\"><span class=\"pre\">libtopsaten.so</span></code> \u7b97\u5b50\u5e93\uff09\u3002\u6784\u5efa\u4f1a\u8fd0\u884c <code class=\"docutils literal notranslate\"><span class=\"pre\">scripts/codegen/codegen_gcu.py</span></code>\uff0c\u6309\u5df2\u5b89\u88c5 <code class=\"docutils literal notranslate\"><span class=\"pre\">libtopsaten.so</span></code> \u4e2d\u5b9e\u9645\u5b58\u5728\u7684 <code class=\"docutils literal notranslate\"><span class=\"pre\">topsaten</span></code> \u7b26\u53f7\u6821\u9a8c\u6bcf\u4e2a\u7b97\u5b50\uff1bSDK \u4e2d\u7f3a\u5931\u7684\u7b97\u5b50\u4f1a\u7ed9\u51fa\u544a\u8b66\u5e76\u8df3\u8fc7\u3002<code class=\"docutils literal notranslate\"><span class=\"pre\">torch-gcu</span></code> wheel \u4e0d\u80fd\u4e0e PyTorch-Plugin-FL \u540c\u65f6\u4f7f\u7528\uff0c\u56e0\u4e3a\u5b83\u4f1a\u81ea\u884c\u5360\u7528 <code class=\"docutils literal notranslate\"><span class=\"pre\">PrivateUse1</span></code>\u3002</p>", "a[href=\"#nvidia-cuda\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">NVIDIA CUDA<a class=\"headerlink\" href=\"#nvidia-cuda\" title=\"Link to this heading\">#</a></h3><p>\u8be5\u6784\u5efa\u6839\u636e PyTorch \u7684 ATen schema \u751f\u6210 CUDA boxing \u5185\u6838\uff0c\u628a <code class=\"docutils literal notranslate\"><span class=\"pre\">libtorch_cuda.so</span></code> \u53ca\u76f8\u5173 CUDA \u8c03\u5ea6\u5e93\u6253\u5305\u5230 <code class=\"docutils literal notranslate\"><span class=\"pre\">torch_fl/lib/</span></code>\uff0c\u5e76\u56fa\u5b9a\u4e0e\u4e4b\u5339\u914d\u7684 <code class=\"docutils literal notranslate\"><span class=\"pre\">nvidia-*-cu12</span></code> \u8fd0\u884c\u671f\u4f9d\u8d56\u3002\u8981\u6c42\uff1a\u8ba1\u7b97\u80fd\u529b 7.0 \u53ca\u4ee5\u4e0a\u7684 NVIDIA GPU\u3001470 \u53ca\u4ee5\u4e0a\u7684\u9a71\u52a8\u3001\u7528\u4e8e\u6784\u5efa\u7684 CUDA 12.x \u5de5\u5177\u5305\uff0c\u4ee5\u53ca <code class=\"docutils literal notranslate\"><span class=\"pre\">cmake</span></code>\u3001<code class=\"docutils literal notranslate\"><span class=\"pre\">ninja</span></code>\u3001<code class=\"docutils literal notranslate\"><span class=\"pre\">patchelf</span></code>\u3002</p><p>\u53ef\u9009\u7684 FlagGems C++ \u8c03\u5ea6\u8def\u5f84\uff08\u5f00\u9500\u6700\u4f4e\u7684 FlagGems \u8def\u7531\uff09\uff1a</p>", "a[href=\"#id2\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u9009\u62e9\u5e73\u53f0<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2><p>\u6bcf\u4e2a\u5e73\u53f0\u7531\u4e00\u4e2a\u6784\u5efa\u53d8\u91cf <code class=\"docutils literal notranslate\"><span class=\"pre\">FLAGOS_ACCELERATOR</span></code> \u9009\u62e9\uff0c\u5e76\u4e14\u5404\u81ea\u6709\u72ec\u7acb\u7684\u6267\u884c\u8def\u5f84\uff1a</p>", "a[href=\"../architecture/torch-compile.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">torch.compile \u96c6\u6210<a class=\"headerlink\" href=\"#torch-compile\" title=\"Link to this heading\">#</a></h1><p><code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code> \u8bbe\u5907\u652f\u6301 <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.compile</span></code>\uff0c\u53ef\u5b9e\u73b0\u81ea\u52a8\u5185\u6838\u878d\u5408\u5e76\u964d\u4f4e\u8c03\u5ea6\u5f00\u9500\u3002\u8ba1\u7b97\u56fe\u59cb\u7ec8\u7559\u5728 <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code> \u8bbe\u5907\u4e0a\uff1a\u4e0d\u5b58\u5728\u8bbe\u5907\u5f80\u8fd4\uff0c\u4e5f\u6ca1\u6709\u56fe\u8fb9\u754c\u5904\u7684\u62f7\u8d1d\u3002</p>", "a[href=\"#id3\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u901a\u7528\u8981\u6c42<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h2><p>\u6240\u6709\u5e73\u53f0\u90fd\u9700\u8981\uff1a</p>", "a[href=\"#bpu\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u5730\u5e73\u7ebf BPU<a class=\"headerlink\" href=\"#bpu\" title=\"Link to this heading\">#</a></h3><p>BPU \u5e73\u53f0\u53ea\u63d0\u4f9b\u8fd0\u884c\u65f6\u52a0\u901f\uff1a\u4e0d\u5b58\u5728\u9010\u7b97\u5b50 BPU \u5185\u6838\uff0ceager \u7b97\u5b50\u901a\u8fc7\u56de\u9000\u5728 CPU \u4e0a\u6267\u884c\uff0c\u52a0\u901f\u6765\u81ea\u6574\u56fe\u7f16\u8bd1\uff08<code class=\"docutils literal notranslate\"><span class=\"pre\">torch.compile(backend=\"bpu\")</span></code>\uff09\u6216\u9884\u6784\u5efa HBM \u7684 LLM \u8fd0\u884c\u65f6\u3002\u56fe\u7f16\u8bd1\u9700\u8981 <code class=\"docutils literal notranslate\"><span class=\"pre\">hbdk4</span></code>\uff0c\u5176 wheel \u4ec5\u63d0\u4f9b x86_64 \u7248\u672c\u3002</p>", "a[href=\"../architecture/distributed.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u5206\u5e03\u5f0f\u96c6\u5408\u901a\u4fe1<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p>PyTorch-Plugin-FL \u901a\u8fc7 <code class=\"docutils literal notranslate\"><span class=\"pre\">ProcessGroupFlagOS</span></code> \u4e3a <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code> \u8bbe\u5907\u63d0\u4f9b\u5206\u5e03\u5f0f\u652f\u6301\u3002\u5b83\u662f\u539f\u751f\u7684 <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.distributed.ProcessGroup</span></code> \u5b50\u7c7b\uff0c\u5728\u5bfc\u5165\u65f6\u5b8c\u6210\u6ce8\u518c\uff0c\u56e0\u6b64 <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.distributed.init_process_group(\"flagos\")</span></code> \u53ef\u76f4\u63a5\u4f7f\u7528\uff0c\u65e0\u9700\u5bf9 <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.distributed.*</span></code> \u505a\u4efb\u4f55 monkeypatch\u3002</p>", "a[href=\"#ascend\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Ascend<a class=\"headerlink\" href=\"#ascend\" title=\"Link to this heading\">#</a></h3><p>\u8981\u6c42\uff1aAscend 910 \u4e0e CANN 9.0.0 \u6216\u517c\u5bb9\u7248\u672c\u3001\u53ef\u8bbf\u95ee\u7684 <code class=\"docutils literal notranslate\"><span class=\"pre\">/dev/davinci*</span></code> \u8bbe\u5907\u8282\u70b9\uff1b\u82e5\u4f7f\u7528 FlagTree Ascend 3.5 wheel\uff08\u4ec5\u63d0\u4f9b cp311\uff09\uff0c\u9700\u8981 Python 3.11\uff0c\u7eaf ACLNN \u6784\u5efa\u5219 Python 3.8+ \u5373\u53ef\u3002</p><p>\u9ed8\u8ba4\u914d\u7f6e\u4e3a\u5df2\u9a8c\u8bc1\u7b97\u5b50\u542f\u7528 FlagGems Python \u8def\u7531\uff0c\u5e76\u4ee5\u539f\u751f ACLNN \u5185\u6838\u4f5c\u4e3a\u56de\u9000\u3002<code class=\"docutils literal notranslate\"><span class=\"pre\">scripts/codegen/codegen_ascend.py</span></code> \u751f\u6210 ACLNN \u5185\u6838\uff1b\u6ca1\u6709 ACLNN \u6620\u5c04\u7684\u7b97\u5b50\u56de\u9000\u5230 CPU\u3002</p>", "a[href=\"#id4\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u6e90\u7801\u5b89\u88c5\u7ea6\u5b9a<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h2><p>\u5404\u5e73\u53f0\u7684\u5b89\u88c5\u9075\u5faa\u540c\u4e00\u6a21\u5f0f\uff1a</p>", "a[href=\"#id7\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u6d4b\u8bd5<a class=\"headerlink\" href=\"#id7\" title=\"Link to this heading\">#</a></h2><p>\u7b97\u5b50\u6d4b\u8bd5\u901a\u8fc7 <code class=\"docutils literal notranslate\"><span class=\"pre\">tests/integration/ops/conftest.py</span></code> \u4e2d\u6ce8\u518c\u7684\u6807\u8bb0\u7b5b\u9009\uff1a</p>", "a[href=\"../architecture/profiler.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Profiler \u96c6\u6210<a class=\"headerlink\" href=\"#profiler\" title=\"Link to this heading\">#</a></h1><p><code class=\"docutils literal notranslate\"><span class=\"pre\">torch.profiler</span></code> \u901a\u8fc7\u7f16\u8bd1\u8fdb wheel \u7684\u8bbe\u5907\u8ffd\u8e2a\u5668\u652f\u6301 <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code> \u8bbe\u5907\u3002<code class=\"docutils literal notranslate\"><span class=\"pre\">torch.profiler.profile(activities=[CPU,</span> <span class=\"pre\">PrivateUse1])</span></code> \u4ea7\u51fa\u7684 trace \u4e0e\u540c\u4e00\u5de5\u4f5c\u8d1f\u8f7d\u5728 <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.cuda</span></code> \u4e0a\u7684 trace \u7ed3\u6784\u7b49\u4ef7\uff1a</p>", "a[href=\"#id6\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u5b89\u88c5\u6821\u9a8c<a class=\"headerlink\" href=\"#id6\" title=\"Link to this heading\">#</a></h2><p>\u5b89\u88c5\u6b63\u5e38\u65f6\u4f1a\u8f93\u51fa\u5f53\u524d\u673a\u5668\u7684\u8bbe\u5907\u6570\u91cf\u4e0e\u4e00\u4e2a\u6d6e\u70b9\u7ed3\u679c\u3002\u82e5\u8bbe\u5907\u6570\u91cf\u4e3a 0\uff0c\u8bf7\u68c0\u67e5\u5382\u5546 SDK \u5b89\u88c5\u3001\u9a71\u52a8\u3001\u8bbe\u5907\u8282\u70b9\u4ee5\u53ca\u4e0a\u6587\u7684\u5bfc\u5165\u987a\u5e8f\u89c4\u5219\u3002</p>", "a[href=\"#id5\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u6784\u5efa\u671f\u5f00\u5173<a class=\"headerlink\" href=\"#id5\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">setup.py</span></code> \u4f1a\u4e3a\u5185\u6838\u96c6\u5408\u5f00\u5173\u5f3a\u5236\u6307\u5b9a\u5404\u5e73\u53f0\u53d6\u503c\uff0c\u5e76\u62d2\u7edd\u4e0e\u4e4b\u77db\u76fe\u7684\u73af\u5883\u53d8\u91cf\u663e\u5f0f\u53d6\u503c\uff1a</p>", "a[href=\"#musa\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u6469\u5c14\u7ebf\u7a0b MUSA<a class=\"headerlink\" href=\"#musa\" title=\"Link to this heading\">#</a></h3><p>\u9700\u8981 <code class=\"docutils literal notranslate\"><span class=\"pre\">/usr/local/musa</span></code> \u4e0b\u7684 MUSA \u5de5\u5177\u5305\uff1a<code class=\"docutils literal notranslate\"><span class=\"pre\">musart</span></code>\uff08\u8fd0\u884c\u65f6\uff09\u3001<code class=\"docutils literal notranslate\"><span class=\"pre\">mudnn</span></code>\uff08\u7b97\u5b50\u5e93\uff09\u4e0e <code class=\"docutils literal notranslate\"><span class=\"pre\">murand</span></code>\uff08\u8bbe\u5907\u968f\u673a\u6570\uff09\u3002\u6784\u5efa\u4f1a\u8fd0\u884c <code class=\"docutils literal notranslate\"><span class=\"pre\">scripts/codegen/codegen_mudnn.py</span></code>\uff1b\u8986\u76d6\u8303\u56f4\u4e3a\u751f\u6210\u7684\u7b97\u5b50\u96c6\u5408\u52a0\u624b\u5199\u5377\u79ef\u5185\u6838\uff0c\u53e6\u6709\u539f\u751f RNG \u5185\u6838\uff0c\u5176\u4f59\u7b97\u5b50\u8d70 CPU \u56de\u9000\u3002\u6b64\u5904 <code class=\"docutils literal notranslate\"><span class=\"pre\">--no-build-isolation</span></code> \u662f\u5f3a\u5236\u8981\u6c42\uff1a\u5426\u5219 pip \u7684\u6784\u5efa\u53e0\u52a0\u5c42\u4f1a\u89e3\u6790\u51fa\u81ea\u5df1\u7684 torch\uff0c\u5bfc\u81f4 <code class=\"docutils literal notranslate\"><span class=\"pre\">import</span> <span class=\"pre\">torch_fl</span></code> \u56e0\u672a\u5b9a\u4e49\u7684 <code class=\"docutils literal notranslate\"><span class=\"pre\">c10</span></code> \u7b26\u53f7\u800c\u5931\u8d25\u3002</p>", "a[href=\"#id1\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u5b89\u88c5<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><h2>\u9009\u62e9\u5e73\u53f0<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2><p>\u6bcf\u4e2a\u5e73\u53f0\u7531\u4e00\u4e2a\u6784\u5efa\u53d8\u91cf <code class=\"docutils literal notranslate\"><span class=\"pre\">FLAGOS_ACCELERATOR</span></code> \u9009\u62e9\uff0c\u5e76\u4e14\u5404\u81ea\u6709\u72ec\u7acb\u7684\u6267\u884c\u8def\u5f84\uff1a</p>", "a[href=\"#id8\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u4e0b\u4e00\u6b65<a class=\"headerlink\" href=\"#id8\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#metax\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">MetaX<a class=\"headerlink\" href=\"#metax\" title=\"Link to this heading\">#</a></h3><p>MetaX \u4f7f\u7528\u81ea\u5305\u542b\u7684 boxing wheel\uff1aCUDA boxing \u5185\u6838\u7528\u5bbf\u4e3b <code class=\"docutils literal notranslate\"><span class=\"pre\">g++</span></code> \u7f16\u8bd1\uff0cMetaX \u5206\u652f\u7248 libtorch C++ \u8fd0\u884c\u65f6\u76f4\u63a5\u6253\u5305\u8fdb wheel\u3002\u76ee\u6807\u673a\u5668\u53ea\u9700\u8981\u5b98\u65b9 <code class=\"docutils literal notranslate\"><span class=\"pre\">torch==2.10.0+cpu</span></code> wheel\u3001<code class=\"docutils literal notranslate\"><span class=\"pre\">torch_fl</span></code> wheel \u4ee5\u53ca <code class=\"docutils literal notranslate\"><span class=\"pre\">/opt/maca</span></code> \u9a71\u52a8\u8fd0\u884c\u65f6\u3002</p><p>wheel \u5728\u5177\u5907\u5b8c\u6574 MACA SDK \u4e0e <code class=\"docutils literal notranslate\"><span class=\"pre\">torch+metax</span></code> wheel\uff08\u4e24\u8005\u5747\u6765\u81ea MetaX \u5f00\u53d1\u8005\u95e8\u6237\uff09\u7684\u673a\u5668\u4e0a\u6784\u5efa\uff1a\u5148\u751f\u6210 boxing \u4ea7\u7269\uff0c\u518d\u7528 <code class=\"docutils literal notranslate\"><span class=\"pre\">scripts/vendor/bundle_maca_libtorch.sh</span></code> \u6253\u5305\u5206\u652f\u7248 libtorch\uff0c\u6700\u540e\u91cd\u65b0\u6253\u5305 wheel\u3002\u4ea7\u7269\u4f53\u79ef\u8f83\u5927\uff08\u6253\u5305\u7684 libtorch \u4f7f\u5176\u8d85\u8fc7 PyPI \u7684\u4f53\u79ef\u9650\u5236\uff09\uff0c\u901a\u8fc7\u79c1\u6709\u6e90\u6216\u76f4\u63a5\u4f20\u8f93\u5206\u53d1\u3002</p>", "a[href=\"../reference/compatibility.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u517c\u5bb9\u6027\u4e0e\u5e73\u53f0\u652f\u6301<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><h2>\u72b6\u6001\u5b9a\u4e49<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#dcu\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u6d77\u5149 DCU<a class=\"headerlink\" href=\"#dcu\" title=\"Link to this heading\">#</a></h3><p>\u8be5\u6784\u5efa\u4e3a\u7eaf boxing\uff1aDTK torch wheel \u628a HIP \u5185\u6838\u6ce8\u518c\u5728 <code class=\"docutils literal notranslate\"><span class=\"pre\">CUDA</span></code> dispatch key \u4e0b\uff0c\u751f\u6210\u7684 boxing \u5185\u6838\u539f\u6837\u5206\u53d1\u5230 <code class=\"docutils literal notranslate\"><span class=\"pre\">libtorch_hip.so</span></code>\uff0c\u8fd0\u884c\u65f6\u6e90\u7801\u7528\u5bbf\u4e3b <code class=\"docutils literal notranslate\"><span class=\"pre\">g++</span></code> \u76f4\u63a5\u7f16\u8bd1 \u2014\u2014 \u4e0d\u9700\u8981 <code class=\"docutils literal notranslate\"><span class=\"pre\">nvcc</span></code>\u3001<code class=\"docutils literal notranslate\"><span class=\"pre\">hipcc</span></code> \u6216 hipify\u3002FlagGems Python \u8def\u5f84\u9ed8\u8ba4\u5f00\u542f\uff1bFlagGems C++ \u8def\u5f84\u4fdd\u6301\u5173\u95ed\uff0c\u56e0\u4e3a DTK \u672a\u63d0\u4f9b <code class=\"docutils literal notranslate\"><span class=\"pre\">liboperators.so</span></code>\u3002</p>", "a[href=\"../reference/environment-variables.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u73af\u5883\u53d8\u91cf<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p>PyTorch-Plugin-FL \u6709\u81ea\u5df1\u7684\u4e00\u5957\u547d\u540d\u7a7a\u95f4 <code class=\"docutils literal notranslate\"><span class=\"pre\">FLAGOS_*</span></code>\uff0c\u53e6\u5916\u8fd8\u4f1a\u8bfb\u53d6\u5c5e\u4e8e\u5176\u4ed6\u9879\u76ee\uff08torch\u3001FlagGems\u3001FlagCX\u3001TileLang\u3001\u5382\u5546 SDK\uff09\u7684\u4e00\u7ec4\u53d8\u91cf\uff0c\u4f46\u4e0d\u62e5\u6709\u5b83\u4eec\u3002\u672c\u9875\u8bb0\u5f55\u7528\u6237\u9700\u8981\u914d\u7f6e\u7684\u53d8\u91cf\uff1b\u5b8c\u6574\u4e14\u6743\u5a01\u7684\u6e05\u5355\u662f <code class=\"docutils literal notranslate\"><span class=\"pre\">torch_fl/_env.py</span></code> \u4e2d\u7684 <code class=\"docutils literal notranslate\"><span class=\"pre\">VARIABLES</span></code> \u6ce8\u518c\u8868\uff0c\u4e0a\u6e38\u4ed3\u5e93\u7684 <code class=\"docutils literal notranslate\"><span class=\"pre\">docs/reference/environment-variables.md</span></code> \u4e0e\u5b83\u9010\u9879\u5bf9\u9f50\uff0c\u5e76\u7531\u5355\u5143\u6d4b\u8bd5\u6821\u9a8c\u3002</p><p>\u8fd9\u91cc\u6ca1\u6709\u4efb\u4f55\u4e00\u9879\u662f\u8fd0\u884c wheel \u6240\u5fc5\u9700\u7684\uff1awheel \u5728\u7a7a\u73af\u5883\u4e0b\u5373\u53ef\u5b8c\u6210\u8def\u7531\u3001\u7f16\u8bd1\u4e0e\u8fd0\u884c\u3002\u8fd9\u4e9b\u53d8\u91cf\u7528\u4e8e\u9009\u62e9\u4e0d\u540c\u7684\u6784\u5efa\u3001\u4e3a\u6d4b\u91cf\u800c\u8986\u76d6\u67d0\u9879\u8bbe\u7f6e\uff0c\u6216\u6253\u5f00\u8bca\u65ad\u3002</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
